import { FC, HTMLAttributes, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { DatePicker, DatePickerProps, Flex, Input, Select } from 'antd';
import dayjs from 'dayjs';

import { EFilters, OPTIONS_MAX_HEIGHT_NOTIFICATIONS, useDateFilters, useFilters } from 'features/Filters';
import { useChannelOptions } from 'shared/hooks';
import { InputClearIcon } from 'shared/ui';

interface IHistoryMainFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const HistoryMainFilters: FC<IHistoryMainFiltersProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const { channelOptions, isFetching } = useChannelOptions();
	const { getFilterValue, onFilterChange } = useFilters();
	const [search, setSearch] = useState(getFilterValue(EFilters.SEARCH) || '');
	const dateFromKey = EFilters.PUBLISHED_AT_FROM;
	const dateToKey = EFilters.PUBLISHED_AT_TO;

	const { dateAfter, dateBefore, onDatesChange } = useDateFilters(dateFromKey, dateToKey);

	const getDefaultValues = (): [dayjs.Dayjs, dayjs.Dayjs] => {
		const dateAfter = dayjs()
			.set('hour', 0)
			.set('minute', 0)
			.set('second', 0)
			.set('millisecond', 0)
			.subtract(1, 'month');
		const dateBefore = dayjs().set('hour', 0).set('minute', 0).set('second', 0).set('millisecond', 0).add(1, 'month');
		return [dateAfter, dateBefore];
	};

	useEffect(() => {
		if (!dateAfter || !dateBefore) {
			onDatesChange(getDefaultValues(), [dateFromKey, dateToKey], true);
		}
	}, [dateAfter, dateBefore]); // eslint-disable-line react-hooks/exhaustive-deps

	const disabledDates: DatePickerProps['disabledDate'] = (current, { from }) => {
		if (from) {
			return Math.abs(current.diff(from, 'month')) > 1;
		}

		return false;
	};

	return (
		<Flex {...props} vertical gap={8}>
			<Input.Search
				placeholder={t('Поиск по офферу, слову')}
				onSearch={(value) => onFilterChange(EFilters.SEARCH, value)}
				onChange={(e) => setSearch(e.target.value)}
				value={search.trimStart()}
				allowClear={{ clearIcon: <InputClearIcon /> }}
				size="large"
			/>

			<DatePicker.RangePicker
				size="large"
				format="DD.MM.YYYY"
				value={[dateAfter, dateBefore]}
				style={{ minWidth: 230 }}
				onChange={(value) => {
					onDatesChange(value, [dateFromKey, dateToKey], true);
				}}
				placeholder={[t('Начало периода'), t('Конец периода')]}
				disabledDate={disabledDates}
			/>

			<Select
				value={getFilterValue(EFilters.CHANNEL_IDS) || t('Все каналы и группы')}
				options={channelOptions}
				onChange={(value) => onFilterChange(EFilters.CHANNEL_IDS, value)}
				placeholder={t('Выберите каналы')}
				size="large"
				showSearch
				optionFilterProp="search"
				allowClear={getFilterValue(EFilters.CHANNEL_IDS) ? { clearIcon: <InputClearIcon /> } : false}
				listHeight={OPTIONS_MAX_HEIGHT_NOTIFICATIONS}
				style={{ width: '100%' }}
				loading={isFetching}
				disabled={isFetching}
			/>
		</Flex>
	);
};
