import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { Flex } from 'antd';

import { useChannelsListQuery } from 'entities/Channel';
import { CHANNELS_LIMIT, EFilters, getUrlParamsForApi, HistoryMainFilters, useFilters } from 'features/Filters';
import { EPaginationParams } from 'features/Pagination';
import { PlannerDay, PlannerPost, PlannerTabs, usePlannerPostsRetrieveQuery } from 'features/Planner';
import { useBackButton } from 'shared/hooks';
import { EMainRoutes } from 'shared/typings';
import { ButtonStyleLink, Content, NoResults, OverlayLoader, Page, PageTitle } from 'shared/ui';
import { formatDate } from 'shared/utils';

import styles from './History.module.scss';

interface IHistoryProps extends HTMLAttributes<HTMLDivElement> {}

export const History: FC<IHistoryProps> = () => {
	const { t } = useTranslation();
	useBackButton(`${EMainRoutes.DASHBOARD}`);

	const [searchParams] = useSearchParams();
	const { data, isFetching } = usePlannerPostsRetrieveQuery(getUrlParamsForApi(searchParams));
	const { data: channelList } = useChannelsListQuery({ [EPaginationParams.LIMIT]: CHANNELS_LIMIT });

	const sortedPosts = [...(data?.results || [])].sort(
		(a, b) => new Date(b.published_at).getTime() - new Date(a.published_at).getTime(),
	);

	const postsMap = sortedPosts.reduce(
		(acc, post) => {
			const date = formatDate(new Date(post.published_at), 'iso') || '';
			acc[date] = [...(acc[date] || []), post];
			return acc;
		},
		{} as Record<string, PlannerPost[]>,
	);

	const { getFiltersCount } = useFilters();

	const hasChannels = !!channelList?.results.length;
	const hasFilters =
		getFiltersCount([EFilters.CHANNEL_IDS, EFilters.PUBLISHED_AT_FROM, EFilters.PUBLISHED_AT_TO, EFilters.SEARCH]) > 0;

	return (
		<Page className={styles.page}>
			<PageTitle subtitle={t('Выберите время или период, когда хотите видеть публикации в своём канале')}>
				{t('Планировщик постов')}
			</PageTitle>

			<PlannerTabs active="2" />

			<Content filled>
				<Flex vertical gap={24}>
					<HistoryMainFilters />

					{isFetching && <OverlayLoader />}

					{!!Object.keys(postsMap).length &&
						Object.keys(postsMap).map((date) => (
							<PlannerDay key={date} posts={postsMap[date]} selectedDate={new Date(date)} isHistory />
						))}

					{!Object.keys(postsMap).length && (
						<NoResults
							text={t('Нет истории')}
							subtext={
								!hasChannels
									? t(
											'К сожалению, пока тут ничего. Для размещения постов, пожалуйста, добавьте свой первый канал или группу',
										)
									: hasFilters
										? t('Нет результатов для этого поискового запроса')
										: t('Ни один пост ещё не был опубликован при помощи Телерев')
							}
							goTo={
								<ButtonStyleLink
									to={hasChannels ? `/${EMainRoutes.CATALOG}` : `/${EMainRoutes.CHANNELS}/${EMainRoutes.CREATE}`}
									block
									type="primary"
									size="large">
									{hasChannels ? t('Добавить из каталога') : t('Добавить')}
								</ButtonStyleLink>
							}
						/>
					)}
				</Flex>
			</Content>
		</Page>
	);
};

export default History;
